package com.lilianluca.ledgerly.data.local.dao

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.Query
import com.lilianluca.ledgerly.data.local.entity.TransactionEntity
import kotlinx.coroutines.flow.Flow

/** Database queries for transactions. The implementation is generated by Room at build time. */
@Dao
interface TransactionDao {

    /** Live query: emits a new list whenever the "transactions" table changes. */
    @Query("SELECT * FROM transactions ORDER BY date DESC, id DESC")
    fun observeAll(): Flow<List<TransactionEntity>>

    /** Inserts the row and returns its generated id. Runs off the main thread. */
    @Insert
    suspend fun insert(transaction: TransactionEntity): Long
}
